// Win-probability logistic coefficients. GENERATED by scripts/fit-winprob.mts from engine match
// data (real rosters, Ascent) and mirrored in winprob-coef.json (the committed artifact). Until the
// fit is run these are the original hand-set values, which keep the model's qualitative behaviour
// (man advantage, plant, defuse, equipment, time). Editing by hand is fine but re-run the fitter to
// refresh both files together. These never enter the simulation — they only shape the viewer's
// estimate, which is pinned to the real result once a round ends.
import type { WpCoef } from './winprob.ts';

export const WP_COEF: WpCoef = {
  b0: 0,
  man: 0.82,
  equip: 0.55,
  plant: 1.15,
  spikeTime: 0.6,
  defuse: -2.6,
  preplant: 0.5,
};

/** Provenance shown in the handoff; overwritten by the fitter. null = still the hand-set defaults. */
export const WP_COEF_META: { fittedAt: string | null; trainSnaps: number | null; valBrier: number | null } = {
  fittedAt: null,
  trainSnaps: null,
  valBrier: null,
};
